text:
{
  "components": [
    {
      "type": "claim",
      "quote": "Le président de la Confédération est « primus inter pares », c'est-à-dire premier parmi ses pairs.",
      "gist": "The President of the Confederation is 'first among equals'."
    },
    {
      "type": "obligation",
      "quote": "Il dirige les séances du Conseil fédéral et arbitre au besoin la discussion.",
      "gist": "He presides over Federal Council sessions and arbitrates discussions when necessary."
    },
    {
      "type": "obligation",
      "quote": "En cas d'urgence, il a la compétence d'ordonner des mesures provisionnelles.",
      "gist": "In emergencies, he has the authority to order provisional measures."
    },
    {
      "type": "obligation",
      "quote": "S'il n'est pas possible de réunir le Conseil fédéral en séance ordinaire ou extraordinaire, le président de la Confédération décide à la place de celui-ci.",
      "gist": "If the Federal Council cannot convene in ordinary or extraordinary session, the President decides on its behalf."
    },
    {
      "type": "claim",
      "quote": "L'Assemblée fédérale élit, outre le président de la Confédération, la vice-présidente ou le vice-président du Conseil fédéral.",
      "gist": "The Federal Assembly elects, in addition to the President of the Confederation, the Vice-President of the Federal Council."
    }
  ]
}
